    public enum RevertReason : Equatable, Error {
        case accountBalanceNotFound(EthAddress)
        case assetPositionNotFound(String)
        case badData
        case badInputInsufficientFunds(String, Number, Number)
        case badInputInsufficientFundsForRecurring(String, Number, Number)
        case bridgeAmountTooLow
        case bridgingUnsupportedForAsset
        case indexOutOfBound
        case invalidActionType
        case invalidAssetForBridge
        case invalidInput
        case invalidRepayActionContext
        case keyNotFound
        case maxCostMissingForChain(Number)
        case maxCostTooHigh
        case missingWrapperCounterpart
        case noKnownAssetQuote(String)
        case noKnownBridge(String, Number)
        case noKnownDomainId(String, Number)
        case notFound(String, Number)
        case notUnwrappable
        case notWrappable
        case quarkSecretNotFound(EthAddress)
        case unableToConstructBridge(String, Number)
        case unableToConstructQuotePay(String, String, Number)
        case unknownAaveMarket(EthAddress, Number)
        case unknownAsset(String, EthAddress, Number)
        case unknownComet(EthAddress, Number)
        case unknownCometRewards(EthAddress, Number)
        case unknownMorphoMarket(Hex, Number)
        case unknownMorphoVault(EthAddress, Number)
        case unknownRevert(String, String)
    }
    public static func rewrapError(_ error: ABI.Function, value: ABI.Value) -> RevertReason {
        switch (error, value) {
        case (AccountBalanceNotFoundError, let .tuple1(.address(account))):
            return .accountBalanceNotFound(account)
        case (AssetPositionNotFoundError, let .tuple1(.string(symbol))):
            return .assetPositionNotFound(symbol)
        case (BadDataError, _):
            return .badData
        case (BadInputInsufficientFundsError, let .tuple3(.string(assetSymbol), .uint256(requiredAmount), .uint256(actualAmount))):
            return .badInputInsufficientFunds(assetSymbol, requiredAmount, actualAmount)
        case (BadInputInsufficientFundsForRecurringError, let .tuple3(.string(assetSymbol), .uint256(requiredAmount), .uint256(actualAmount))):
            return .badInputInsufficientFundsForRecurring(assetSymbol, requiredAmount, actualAmount)
        case (BridgeAmountTooLowError, _):
            return .bridgeAmountTooLow
        case (BridgingUnsupportedForAssetError, _):
            return .bridgingUnsupportedForAsset
        case (IndexOutOfBoundError, _):
            return .indexOutOfBound
        case (InvalidActionTypeError, _):
            return .invalidActionType
        case (InvalidAssetForBridgeError, _):
            return .invalidAssetForBridge
        case (InvalidInputError, _):
            return .invalidInput
        case (InvalidRepayActionContextError, _):
            return .invalidRepayActionContext
        case (KeyNotFoundError, _):
            return .keyNotFound
        case (MaxCostMissingForChainError, let .tuple1(.uint256(chainId))):
            return .maxCostMissingForChain(chainId)
        case (MaxCostTooHighError, _):
            return .maxCostTooHigh
        case (MissingWrapperCounterpartError, _):
            return .missingWrapperCounterpart
        case (NoKnownAssetQuoteError, let .tuple1(.string(symbol))):
            return .noKnownAssetQuote(symbol)
        case (NoKnownBridgeError, let .tuple2(.string(bridgeType), .uint256(srcChainId))):
            return .noKnownBridge(bridgeType, srcChainId)
        case (NoKnownDomainIdError, let .tuple2(.string(bridgeType), .uint256(dstChainId))):
            return .noKnownDomainId(bridgeType, dstChainId)
        case (NotFoundError, let .tuple2(.string(message), .uint256(chainId))):
            return .notFound(message, chainId)
        case (NotUnwrappableError, _):
            return .notUnwrappable
        case (NotWrappableError, _):
            return .notWrappable
        case (QuarkSecretNotFoundError, let .tuple1(.address(account))):
            return .quarkSecretNotFound(account)
        case (UnableToConstructBridgeError, let .tuple2(.string(bridgeAssetSymbol), .uint256(bridgeFees))):
            return .unableToConstructBridge(bridgeAssetSymbol, bridgeFees)
        case (UnableToConstructQuotePayError, let .tuple3(.string(quotePayStatus), .string(paymentAssetSymbol), .uint256(quoteAmount))):
            return .unableToConstructQuotePay(quotePayStatus, paymentAssetSymbol, quoteAmount)
        case (UnknownAaveMarketError, let .tuple2(.address(aavePool), .uint256(chainId))):
            return .unknownAaveMarket(aavePool, chainId)
        case (UnknownAssetError, let .tuple3(.string(assetSymbol), .address(assetAddress), .uint256(chainId))):
            return .unknownAsset(assetSymbol, assetAddress, chainId)
        case (UnknownCometError, let .tuple2(.address(comet), .uint256(chainId))):
            return .unknownComet(comet, chainId)
        case (UnknownCometRewardsError, let .tuple2(.address(cometReward), .uint256(chainId))):
            return .unknownCometRewards(cometReward, chainId)
        case (UnknownMorphoMarketError, let .tuple2(.bytes32(marketId), .uint256(chainId))):
            return .unknownMorphoMarket(marketId, chainId)
        case (UnknownMorphoVaultError, let .tuple2(.address(morphoVault), .uint256(chainId))):
            return .unknownMorphoVault(morphoVault, chainId)
        case let (e, v):
            return .unknownRevert(e.name, String(describing: v))
        }
    }
